head.script:
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행한다.
    //1. Run the sample file.
    // verify step 1. checkcombobox, selectbox 값에 동일하게 3이 보여진
    //1. checkcombobox, 3 is shown in the selectbox value as well.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('ccb_inrv_rslt_cd').getText()", "3");
    // Test step 2. checkcombobox 값을 변경한다.(3값을 체크해지하고 2값을 체크로 변경)
    //2. Change the value of checkcombobox (uncheck 3 and change 2 to check)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('ccb_inrv_rslt_cd').setText('2')");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 2. selectbox 값도 동일하게 2값으로 변경되어진다.
    //2. The value of selectbox is also changed to 2.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('select1').getText()", "2");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. selectbox 값을 변경한다.
    //3. Change the value of the selectbox.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('select1').setText('1')");
    // verify step 3.checkcombobox 값도 동일하게 변경되어진다.
    //3. The checkcombobox value is also changed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('ccb_inrv_rslt_cd').getText()", "1");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setData(["1", "1", "2", "2", "3", "3"]);
    dataMap1.set("key1", "3");
    //Function unitTest
    //Created By: Sang.do
    //Created By: 23-Jan-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
